from pathlib import Path
import json
code=r'''using System;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;public static class Inspect102{public static string Run(){var b=new StringBuilder();var root=GameObject.Find("Lobby_Island_Visual_Prototype").transform;var boats=root.Find("04_Boat_Skins_Showcase");foreach(Transform t in boats)b.AppendLine("ROOT "+t.name+" pos="+t.localPosition+" active="+t.gameObject.activeSelf);foreach(Transform t in boats.Find("Luxury_Boat_Salon095"))b.AppendLine("SALON "+t.name+" pos="+t.localPosition+" active="+t.gameObject.activeSelf);foreach(string n in new[]{"pirate_officer","pirate_captain","pirate_crew"}){var a=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Import/Kenney Assets/Pirate Kit/Models/FBX format/"+n+".fbx");b.AppendLine(n+" rot="+a.transform.localEulerAngles+" meshes="+a.GetComponentsInChildren<MeshFilter>().Length+" skinned="+a.GetComponentsInChildren<SkinnedMeshRenderer>().Length);}System.IO.File.WriteAllText("Library/WorkshopBackups/DB-ON-102/inspect.txt",b.ToString());return b.ToString();}}'''
Path('Library/WorkshopBackups/DB-ON-102/inspect.json').write_text(json.dumps({'csharpCode':code,'className':'Inspect102','methodName':'Run'}),encoding='utf-8')
